package com.openjiuwen.workbench.deep;
import com.openjiuwen.core.foundation.tool.ToolCard;
import com.openjiuwen.core.foundation.tool.function.LocalFunction;
import java.nio.file.*;
import java.io.IOException;
import java.util.*;
import java.util.function.Consumer;
/** One bounded, per-conversation artifact. No shell or arbitrary filesystem access. */
public final class ArtifactTools {
 private final Path root;private final Consumer<Map<String,Object>> events;private boolean wrote,readBack,selectionRequired,skillLoaded;private Set<String> allowed=Set.of();private String lastRead;
 public ArtifactTools(Path root,Consumer<Map<String,Object>> events){try{Files.createDirectories(root);if(Files.isSymbolicLink(root))throw new IllegalArgumentException("INVALID_WORKSPACE");this.root=root.toRealPath();}catch(IOException e){throw new IllegalStateException("WORKSPACE_UNAVAILABLE");}this.events=events;}
 public synchronized void beginTurn(){wrote=false;readBack=false;lastRead=null;if(selectionRequired){allowed=Set.of();skillLoaded=false;}}
 public synchronized void requireSelection(boolean required){selectionRequired=required;}
 public synchronized void selectSkill(String id,Set<String> operations){allowed=Set.copyOf(operations);skillLoaded=true;events.accept(Map.of("type","skill_loaded","skill",id,"operations",operations));}
 private void authorize(String operation){if(selectionRequired&&!skillLoaded)throw new IllegalArgumentException("SKILL_LOAD_REQUIRED_THIS_TURN");if(selectionRequired&&!allowed.contains(operation))throw new IllegalArgumentException("OPERATION_NOT_ASSEMBLED_FOR_SKILL");}
 public synchronized boolean verified(){return wrote&&readBack;}
 private Path target(String name){if(!"brief.md".equals(name))throw new IllegalArgumentException("ONLY_BRIEF_MD_ALLOWED");Path p=root.resolve(name);if(Files.isSymbolicLink(p))throw new IllegalArgumentException("SYMLINK_NOT_ALLOWED");return p;}
 public synchronized String read(String name){authorize("read_file");try{Path p=target(name);if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||Files.size(p)>100000)throw new IllegalArgumentException("ARTIFACT_UNAVAILABLE");String text=Files.readString(p);lastRead=text;if(wrote)readBack=true;events.accept(Map.of("type","artifact_read","file",name));return text;}catch(IOException e){throw new IllegalStateException("ARTIFACT_READ_FAILED");}}
 public synchronized Map<String,Object> write(String name,String text){authorize("write_file");if(text==null||text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>50000)throw new IllegalArgumentException("ARTIFACT_TOO_LARGE");try{Path path=target(name);if(selectionRequired&&allowed.contains("replace_text")&&Files.exists(path,LinkOption.NOFOLLOW_LINKS))throw new IllegalArgumentException("ARTIFACT_EXISTS_USE_REPLACE_TEXT");Files.writeString(path,text,StandardOpenOption.CREATE,StandardOpenOption.TRUNCATE_EXISTING,LinkOption.NOFOLLOW_LINKS);wrote=true;readBack=false;lastRead=null;events.accept(Map.of("type","artifact_written","file",name,"bytes",text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length));return Map.of("success",true,"file_path",name);}catch(IOException e){throw new IllegalStateException("ARTIFACT_WRITE_FAILED");}}
 public synchronized Map<String,Object> replace(String name,String oldText,String newText){
  authorize("replace_text");if(oldText==null||oldText.isEmpty()||newText==null||oldText.equals(newText))throw new IllegalArgumentException("INVALID_REPLACEMENT");
  if(oldText.length()>50000||newText.length()>50000)throw new IllegalArgumentException("ARTIFACT_TOO_LARGE");
  try{Path path=target(name);if(lastRead==null||!Files.isRegularFile(path,LinkOption.NOFOLLOW_LINKS)||Files.size(path)>50000)throw new IllegalArgumentException("READ_ORIGINAL_REQUIRED");String original=Files.readString(path);if(!original.equals(lastRead))throw new IllegalArgumentException("ARTIFACT_CHANGED_READ_AGAIN");if(!original.contains(oldText))throw new IllegalArgumentException("REPLACEMENT_ANCHOR_NOT_FOUND");
   int count=0;for(int pos=0;(pos=original.indexOf(oldText,pos))>=0;pos+=oldText.length())count++;
   long estimated=original.getBytes(java.nio.charset.StandardCharsets.UTF_8).length+(long)count*(newText.getBytes(java.nio.charset.StandardCharsets.UTF_8).length-oldText.getBytes(java.nio.charset.StandardCharsets.UTF_8).length);if(estimated>50000||estimated<0)throw new IllegalArgumentException("ARTIFACT_TOO_LARGE");
   String updated=original.replace(oldText,newText);int bytes=updated.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(bytes>50000)throw new IllegalArgumentException("ARTIFACT_TOO_LARGE");
   Files.writeString(path,updated,StandardOpenOption.TRUNCATE_EXISTING,LinkOption.NOFOLLOW_LINKS);wrote=true;readBack=false;lastRead=null;events.accept(Map.of("type","artifact_patched","file",name,"replacements",count,"bytes",bytes));return Map.of("success",true,"file_path",name,"replacements",count);
  }catch(IOException e){throw new IllegalStateException("ARTIFACT_WRITE_FAILED");}
 }
 public synchronized List<Map<String,Object>> artifacts(){Path p=target("brief.md");try{return Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)&&Files.size(p)<=50000?List.of(Map.of("path","brief.md","content",Files.readString(p))):List.of();}catch(IOException e){throw new IllegalStateException("ARTIFACT_READ_FAILED");}}
 private static Map<String,Object> failure(RuntimeException e){String code=Objects.toString(e.getMessage(),"TOOL_FAILED");return Map.of("success",false,"error",code,"hint",code.equals("SKILL_LOAD_REQUIRED_THIS_TURN")?"请先调用skill_tool加载本轮已装配Skill，再使用文件工具；上轮授权不自动续用。":code.equals("ARTIFACT_EXISTS_USE_REPLACE_TEXT")?"原稿已存在：先read_file，再用replace_text按old_text/new_text做精确替换，其他字符保留，最后读回。":"检查当前Skill的允许操作和文件参数；不能改用未装配工具。");}
 public List<Object> tools(){String prefix=UUID.randomUUID().toString();Map<String,Object> file=Map.of("type","object","properties",Map.of("file_path",Map.of("type","string","enum",List.of("brief.md"))),"required",List.of("file_path"),"additionalProperties",false);
  return List.of(new LocalFunction(ToolCard.builder().id(prefix+"-read").name("read_file").description("读取当前会话的 brief.md，写入后必须读回核对").inputParams(file).build(),args->{try{return Map.of("success",true,"content",read(Objects.toString(args.get("file_path"),"")));}catch(RuntimeException e){return failure(e);}}),
   new LocalFunction(ToolCard.builder().id(prefix+"-write").name("write_file").description("创建或更新当前会话 brief.md，后续必须读回").inputParams(Map.of("type","object","properties",Map.of("file_path",Map.of("type","string","enum",List.of("brief.md")),"content",Map.of("type","string","maxLength",50000)),"required",List.of("file_path","content"),"additionalProperties",false)).build(),args->{try{return write(Objects.toString(args.get("file_path"),""),Objects.toString(args.get("content"),""));}catch(RuntimeException e){return failure(e);}}),
   new LocalFunction(ToolCard.builder().id(prefix+"-replace").name("replace_text").description("先read_file，按字面量old_text全部替换为new_text，其他字符不变；修改brief.md后必须读回").inputParams(Map.of("type","object","properties",Map.of("file_path",Map.of("type","string","enum",List.of("brief.md")),"old_text",Map.of("type","string","minLength",1,"maxLength",50000),"new_text",Map.of("type","string","maxLength",50000)),"required",List.of("file_path","old_text","new_text"),"additionalProperties",false)).build(),args->{try{return replace(Objects.toString(args.get("file_path"),""),Objects.toString(args.get("old_text"),""),Objects.toString(args.get("new_text"),""));}catch(RuntimeException e){return failure(e);}}),
   new LocalFunction(ToolCard.builder().id(prefix+"-list").name("list_files").description("列出本会话的整理稿文件").inputParams(Map.of("type","object","properties",Map.of(),"additionalProperties",false)).build(),args->{try{authorize("list_files");return Map.of("success",true,"files",artifacts().isEmpty()?List.of():List.of("brief.md"));}catch(RuntimeException e){return failure(e);}}));
 }
}
